  '#464555':   { token: 'colors.textSecondary',          hex: '#464555',  frequency: 15 },
  '#5d5fef':   { token: 'colors.primaryContainer',       hex: '#5d5fef',  frequency: 14 },
  '#1a1a2e':   { token: 'colors.textPrimary',            hex: '#1a1a2e',  frequency: 10 },

  // === MEDIUM FREQUENCY (4-9 times) ===
  '#dedfe5':   { token: 'colors.secondaryContainer',     hex: '#dedfe5',  frequency: 8 },
  '#434343':   { token: 'colors.textPrimary',            hex: '#1a1a2e',  frequency: 8 },  // Figma-specific dark, map to textPrimary
  '#5c5e63':   { token: 'colors.textSecondary',          hex: '#5c5e63',  frequency: 8 },
  '#fcfcfd':   { token: 'colors.surfaceContainerLowest', hex: '#ffffff',  frequency: 7 },  // Near-white, map to surface
  '#efecff':   { token: 'colors.surfaceContainer',       hex: '#efecff',  frequency: 7 },
  '#e8e8e9':   { token: 'colors.secondaryContainer',     hex: '#dedfe5',  frequency: 4 },  // Near-secondary
  '#010101':   { token: 'colors.textPrimary',            hex: '#1a1a2e',  frequency: 4 },  // Near-black
  '#d5d5d6':   { token: 'colors.outlineVariant',         hex: '#c7c4d7',  frequency: 4 },  // Near-outline
  '#000000':   { token: 'colors.textPrimary',            hex: '#1a1a2e',  frequency: 4 },

  // === LOW FREQUENCY (1-2 times) ===
  '#ba1a1a':   { token: 'colors.error',                  hex: '#ba1a1a',  frequency: 2 },
  '#fafafb':   { token: 'colors.surfaceContainerLowest', hex: '#ffffff',  frequency: 2 },
  '#e2e0fc':   { token: 'colors.surfaceVariant',         hex: '#e2e0fc',  frequency: 2 },
