  '#c1c1ff':   { token: 'colors.inversePrimary',         hex: '#c1c1ff',  frequency: 1 },
  '#ffdad6':   { token: 'colors.errorContainer',         hex: '#ffdad6',  frequency: 1 },
  '#22c55e':   { token: 'colors.primary',                hex: '#4343d5',  frequency: 1 },  // Green (success), map to primary

  // === SINGLE-USE (1 time) ===
  '#fffbeb':   { token: 'colors.surfaceContainerLow',    hex: '#f5f2ff',  frequency: 1 }, // Warm bg
  '#ecfdf5':   { token: 'colors.surfaceContainerLow',    hex: '#f5f2ff',  frequency: 1 }, // Mint bg
  '#454545':   { token: 'colors.textSecondary',          hex: '#5c5e63',  frequency: 1 },
  '#f5f3ff':   { token: 'colors.surfaceContainerLow',    hex: '#f5f2ff',  frequency: 1 },
  '#e5e5e6':   { token: 'colors.secondaryContainer',     hex: '#dedfe5',  frequency: 1 },
