  '#f5f5f6':   { token: 'colors.surfaceContainerLow',    hex: '#f5f2ff',  frequency: 1 },
  '#faf5ff':   { token: 'colors.surface',                hex: '#fcf8ff',  frequency: 1 }, // Purple bg
  '#dededf':   { token: 'colors.secondaryContainer',     hex: '#dedfe5',  frequency: 1 },
